import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

void main() => runApp(const N3MStoreApp());

const waNumber = '62882003887984';
const danaNumber = '0882008839182';
const danaName = 'Nandy Febrya Nova Pratama';
const qrisId = 'ID1026593068855';
const services = <String, int>{'Followers':17000,'Likes':5000,'Saves':5000,'Views':10000,'Comments':20000,'Shares':2000};
String rupiah(int n) => 'Rp ${n.toString().replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'), (_) => '.')}';

class StoreOrder { final String service, target, payment; final int qty, price; final DateTime date; StoreOrder(this.service,this.target,this.qty,this.price,this.payment):date=DateTime.now(); }

class N3MStoreApp extends StatelessWidget { const N3MStoreApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:'N3MSTORE',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:Colors.black),scaffoldBackgroundColor:const Color(0xfff5f5f5),appBarTheme:const AppBarTheme(backgroundColor:Colors.white,foregroundColor:Colors.black)),home:const StoreShell()); }

class StoreShell extends StatefulWidget { const StoreShell({super.key}); @override State<StoreShell> createState()=>_StoreShellState(); }
class _StoreShellState extends State<StoreShell> { int tab=0; final List<StoreOrder> orders=[]; @override Widget build(BuildContext context){ final pages=[HomePage(onShop:()=>setState(()=>tab=1)),const FeedPage(),ServicePage(onOrder:(o){setState(()=>orders.insert(0,o)); Navigator.push(context,MaterialPageRoute(builder:(_)=>PaymentPage(order:o)));}),OrderPage(orders:orders),const ProfilePage()]; return Scaffold(appBar:AppBar(title:const Text('N3MSTORE',style:TextStyle(fontWeight:FontWeight.w900,letterSpacing:1.4)),centerTitle:false),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.feed_outlined),label:'Feed'),NavigationDestination(icon:Icon(Icons.shopping_bag_outlined),label:'Layanan'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'Pesanan'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profil') ])); } }

Widget heading(String s)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Text(s,style:const TextStyle(fontSize:19,fontWeight:FontWeight.w800)));
Widget darkButton(String text,VoidCallback fn)=>SizedBox(width:double.infinity,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:Colors.black,foregroundColor:Colors.white,padding:const EdgeInsets.symmetric(vertical:15)),onPressed:fn,child:Text(text)));
Future<void> openWA(String message) async { final uri=Uri.parse('https://wa.me/$waNumber?text=${Uri.encodeComponent(message)}'); await launchUrl(uri,mode:LaunchMode.externalApplication); }

class HomePage extends StatelessWidget { final VoidCallback onShop; const HomePage({super.key,required this.onShop}); @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:Colors.black,borderRadius:BorderRadius.circular(22)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('DIGITAL SERVICE STORE',style:TextStyle(color:Colors.white70,letterSpacing:1.5)),SizedBox(height:8),Text('WELCOME TO\nN3MSTORE',style:TextStyle(color:Colors.white,fontSize:30,fontWeight:FontWeight.w900,height:1.1)),SizedBox(height:10),Text('Layanan kebutuhan engagement TikTok dalam satu tempat.',style:TextStyle(color:Colors.white70))])),const SizedBox(height:20),heading('Layanan tersedia'),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:2.3,crossAxisSpacing:10,mainAxisSpacing:10,children:services.entries.map((e)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Text(e.key,style:const TextStyle(fontWeight:FontWeight.bold)),Text('${rupiah(e.value)} / 100',style:const TextStyle(color:Colors.black54,fontSize:12))])))).toList()),const SizedBox(height:16),darkButton('PESAN SEKARANG',onShop),const SizedBox(height:14),const Card(child:ListTile(leading:Icon(Icons.verified_user_outlined),title:Text('Transaksi lebih terarah'),subtitle:Text('Periksa detail pesanan dan pembayaran sebelum menghubungi admin.'))),const Card(child:ListTile(leading:Icon(Icons.support_agent),title:Text('Bantuan admin'),subtitle:Text('+62 882-0038-87984')))]); }

