class FeedCard extends StatelessWidget {final IconData icon;final String title,body;const FeedCard({super.key,required this.icon,required this.title,required this.body});@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,size:25),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),const SizedBox(height:6),Text(body,style:const TextStyle(height:1.4,color:Colors.black87))]))])));}

class ServicePage extends StatefulWidget {final ValueChanged<StoreOrder> onOrder;const ServicePage({super.key,required this.onOrder});@override State<ServicePage> createState()=>_ServicePageState();}
class _ServicePageState extends State<ServicePage>{String service='Followers';int qty=100;final target=TextEditingController();int get price=services[service]!*qty~/100;@override void dispose(){target.dispose();super.dispose();}void create(){if(target.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Masukkan link akun atau konten TikTok.')));return;}final o=StoreOrder(service,target.text.trim(),qty,price,'Belum dipilih');widget.onOrder(o);}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[heading('Buat pesanan'),DropdownButtonFormField<String>(value:service,decoration:const InputDecoration(labelText:'Pilih layanan',border:OutlineInputBorder(),filled:true,fillColor:Colors.white),items:services.keys.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>setState(()=>service=v!)),const SizedBox(height:12),DropdownButtonFormField<int>(value:qty,decoration:const InputDecoration(labelText:'Jumlah',border:OutlineInputBorder(),filled:true,fillColor:Colors.white),items:[100,500,1000,5000,10000].map((q)=>DropdownMenuItem(value:q,child:Text('$q ${service.toLowerCase()}'))).toList(),onChanged:(v)=>setState(()=>qty=v!)),const SizedBox(height:12),TextField(controller:target,decoration:const InputDecoration(labelText:'Link akun / konten TikTok',hintText:'https://www.tiktok.com/@username',border:OutlineInputBorder(),filled:true,fillColor:Colors.white)),const SizedBox(height:14),Card(child:ListTile(title:const Text('Total pembayaran'),subtitle:Text('$service • $qty'),trailing:Text(rupiah(price),style:const TextStyle(fontWeight:FontWeight.w900,fontSize:17)))),const SizedBox(height:10),darkButton('LANJUT KE PEMBAYARAN',create),const SizedBox(height:12),const Text('Harga dihitung proporsional dari harga dasar per 100. Jangan pernah memberikan password atau OTP akun.',style:TextStyle(color:Colors.black54))]);}

